{
  "$schema": "https://opencode.ai/config.json",
  "agent": {
    "luna-build": {
      "description": "Full development agent using Azure GPT-5.6 Luna at medium reasoning effort",
      "mode": "primary",
      "model": "openai/gpt-5.6-luna",
      "reasoningEffort": "medium"
    },
    "luna-max": {
      "description": "Full development agent using Azure GPT-5.6 Luna at max reasoning effort",
      "mode": "primary",
      "model": "openai/gpt-5.6-luna",
      "reasoningEffort": "max"
    },
    "terra-high": {
      "description": "Full development agent using Azure GPT-5.6 Terra at high reasoning effort",
      "mode": "primary",
      "model": "openai/gpt-5.6-terra",
      "reasoningEffort": "high"
    },
    "terra-max": {
      "description": "Full development agent using Azure GPT-5.6 Terra at max reasoning effort",
      "mode": "primary",
      "model": "openai/gpt-5.6-terra",
      "reasoningEffort": "max"
    }
  },
  "provider": {
    "openai": {
      "options": {
        "baseURL": "{env:AUTO_AZURE_BASE_URL}",
        "apiKey": "{env:AUTO_AZURE_API_KEY}"
      },
      "models": {
        "gpt-5.6-luna": {
          "name": "GPT-5.6 Luna (Azure)"
        },
        "gpt-5.6-terra": {
          "name": "GPT-5.6 Terra (Azure)"
        }
      }
    }
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "agent": {
    "muse-auto": {
      "description": "Muse Spark 1.3 Free XHigh for Superset AUTO",
      "mode": "primary",
      "model": "opencode/muse-spark-1.3-contributor-free",
      "variant": "xhigh"
    },
    "muse-go-auto": {
      "description": "Muse Spark 1.3 Go XHigh for Superset AUTO fallback",
      "mode": "primary",
      "model": "opencode-go/muse-spark-1.3-contributor",
      "variant": "xhigh"
    }
  }
}
